/**
 * This file is part of helpers4.
 * Copyright (C) 2026 baxyz
 * SPDX-License-Identifier: LGPL-3.0-or-later
 */

import { clamp } from '../number/clamp';
import { roundTo } from '../number/roundTo';
import type { RgbColor } from './hexToRgb';
import { premultiply } from './premultiply';
import { unpremultiply } from './unpremultiply';

/**
 * Mixes two colors in sRGB, as CSS `color-mix(in srgb, color P%, base)` does: `percent`% of
 * `color` and the rest of `base`. Alpha is interpolated in premultiplied space (CSS Color 4), so a
 * translucent color weighs less in the result. Opaque colors give a plain weighted average of the
 * channels.
 *
 * @param color - The color to mix in
 * @param base - The color it is mixed into
 * @param percent - Share of `color`, from 0 (all `base`) to 100 (all `color`); clamped. Defaults to 50.
 * @throws {RangeError} If `percent` is `NaN`
 * @returns The straight result: channels rounded to integers, alpha to 3 decimals
 * @example
 * mixColors({ r: 255, g: 0, b: 0 }, { r: 0, g: 0, b: 255 }, 25) // => { r: 64, g: 0, b: 191, a: 1 }
 * @example
 * mixColors({ r: 255, g: 0, b: 0, a: 0.5 }, { r: 0, g: 0, b: 255 }) // => { r: 85, g: 0, b: 170, a: 0.75 }
 * @since next
 */
export function mixColors(color: RgbColor, base: RgbColor, percent = 50): RgbColor {
  if (Number.isNaN(percent)) throw new RangeError('mixColors: percent must be a number');
  const p = clamp(percent, 0, 100) / 100;
  const c = premultiply(color);
  const d = premultiply(base);
  const mixed = unpremultiply({
    r: c.r * p + d.r * (1 - p),
    g: c.g * p + d.g * (1 - p),
    b: c.b * p + d.b * (1 - p),
    a: c.a! * p + d.a! * (1 - p),
  });
  return { r: Math.round(mixed.r), g: Math.round(mixed.g), b: Math.round(mixed.b), a: roundTo(mixed.a!, 3) };
}

helpers/commit/analyzeCommits.ts.source:
/**
 * This file is part of helpers4.
 * Copyright (C) 2025 baxyz
 * SPDX-License-Identifier: LGPL-3.0-or-later
 */

import { parseConventionalCommit } from './parseConventionalCommit';
import type { AnalyzableCommit, CommitAnalysis, CommitVersionBump } from './types';

const BREAKING_MARKER = /^BREAKING[ -]CHANGE: /m;

/**
 * Analyses a list of commits to suggest a semantic version bump.
 *
 * Each commit is parsed via `parseConventionalCommit`. The body is also
 * scanned for `BREAKING CHANGE:` / `BREAKING-CHANGE:` markers. The bump rule
 * is:
 *
 * - any breaking change → `'major'`
 * - otherwise any `feat` → `'minor'`
 * - otherwise any `fix` → `'patch'`
 * - otherwise (non-empty list of non-conventional commits) → `'patch'`
 * - empty list → `'patch'` with reason "No commits to analyse"
 *
 * @param commits - Iterable of commits to analyse. Only `subject` is required.
 * @returns Aggregated analysis with the suggested bump and reason.
 * @example
 * analyzeCommits([{ subject: 'feat: add x' }, { subject: 'fix: bug' }])
 * // => { suggestedBump: 'minor', hasFeatures: true, hasFixes: true, ... }
 *
 * analyzeCommits([{ subject: 'feat!: drop v1' }])
 * // => { suggestedBump: 'major', hasBreakingChanges: true, ... }
 * @since 2.0.0
 */
export function analyzeCommits(commits: readonly AnalyzableCommit[]): CommitAnalysis {
  let hasBreakingChanges = false;
  let hasFeatures = false;
  let hasFixes = false;

  for (const commit of commits) {
    const fullMessage = commit.body
      ? `${commit.subject}\n\n${commit.body}`
      : commit.subject;
    const parsed = parseConventionalCommit(fullMessage);

    if (parsed) {
      if (parsed.breaking) hasBreakingChanges = true;
      if (parsed.type === 'feat') hasFeatures = true;
      if (parsed.type === 'fix') hasFixes = true;
    } else if (commit.body && BREAKING_MARKER.test(commit.body.replace(/\r\n/g, '\n'))) {
      hasBreakingChanges = true;
    }
  }

  let suggestedBump: CommitVersionBump;
  let reason: string;

  if (hasBreakingChanges) {
    suggestedBump = 'major';
    reason = 'Breaking changes detected in commits';
  } else if (hasFeatures) {
    suggestedBump = 'minor';
    reason = 'New features detected in commits';
  } else if (hasFixes) {
    suggestedBump = 'patch';
    reason = 'Bug fixes detected in commits';
  } else if (commits.length > 0) {
    suggestedBump = 'patch';
    reason = 'Changes detected but no conventional commit types found';
  } else {
    suggestedBump = 'patch';
    reason = 'No commits to analyse';
  }

  return {
    suggestedBump,
    reason,
    hasBreakingChanges,
    hasFeatures,
    hasFixes,
  };
}

