 */

import { describe, expect, it } from 'vitest';
import { parse } from './parse';
import { stringify } from './stringify';

describe('parse', () => {
  describe('core version parsing', () => {
    it('should parse basic version', () => {
      expect(parse('1.2.3')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 2,
        patch: 3,
        prerelease: [],
        build: [],
      });
    });

    it('should parse version with v prefix', () => {
      expect(parse('v1.2.3')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 2,
        patch: 3,
        prerelease: [],
        build: [],
      });
    });

    it('should parse version 0.0.0', () => {
      expect(parse('0.0.0')).toEqual({
        scheme: 'semver',
        major: 0,
        minor: 0,
        patch: 0,
        prerelease: [],
        build: [],
      });
    });

    it('should parse large version numbers', () => {
      expect(parse('100.200.300')).toEqual({
        scheme: 'semver',
        major: 100,
        minor: 200,
        patch: 300,
        prerelease: [],
        build: [],
      });
    });

    it('should handle missing parts as 0', () => {
      expect(parse('1.2')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 2,
        patch: 0,
        prerelease: [],
        build: [],
      });

      expect(parse('1')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: [],
        build: [],
      });
    });
  });

  describe('prerelease parsing', () => {
    it('should parse simple prerelease', () => {
      expect(parse('1.0.0-alpha')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: ['alpha'],
        build: [],
      });
    });

    it('should parse prerelease with number', () => {
      expect(parse('1.0.0-alpha.1')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: ['alpha', '1'],
        build: [],
      });
    });

    it('should parse numeric prerelease', () => {
      expect(parse('1.0.0-0.3.7')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: ['0', '3', '7'],
        build: [],
      });
    });

    it('should parse complex prerelease', () => {
      expect(parse('1.0.0-x.7.z.92')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: ['x', '7', 'z', '92'],
        build: [],
      });
    });

    it('should parse common prerelease tags', () => {
      expect(parse('2.0.0-beta')).toEqual({
        scheme: 'semver',
        major: 2,
        minor: 0,
        patch: 0,
        prerelease: ['beta'],
        build: [],
      });

      expect(parse('3.0.0-rc.1')).toEqual({
        scheme: 'semver',
        major: 3,
        minor: 0,
        patch: 0,
        prerelease: ['rc', '1'],
        build: [],
      });
    });

    it('should parse prerelease with v prefix', () => {
      expect(parse('v1.0.0-alpha.1')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: ['alpha', '1'],
        build: [],
      });
    });
  });

  describe('build metadata parsing', () => {
    it('should parse simple build metadata', () => {
      expect(parse('1.0.0+build')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: [],
        build: ['build'],
      });
    });

    it('should parse numeric build metadata', () => {
      expect(parse('1.0.0+20130313144700')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: [],
        build: ['20130313144700'],
      });
    });

    it('should parse complex build metadata', () => {
      expect(parse('1.0.0+exp.sha.5114f85')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: [],
        build: ['exp', 'sha', '5114f85'],
      });
    });

    it('should parse build metadata with dashes', () => {
      expect(parse('1.0.0+21AF26D3----117B344092BD')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: [],
        build: ['21AF26D3----117B344092BD'],
      });
    });
  });

  describe('prerelease and build metadata combined', () => {
    it('should parse prerelease with build metadata', () => {
      expect(parse('1.0.0-alpha+001')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: ['alpha'],
        build: ['001'],
      });
    });

    it('should parse complex prerelease with build metadata', () => {
      expect(parse('1.0.0-beta+exp.sha.5114f85')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: ['beta'],
        build: ['exp', 'sha', '5114f85'],
      });
    });

    it('should parse SemVer spec example', () => {
      expect(parse('1.0.0-alpha.1+build.123')).toEqual({
        scheme: 'semver',
        major: 1,
        minor: 0,
        patch: 0,
        prerelease: ['alpha', '1'],
        build: ['build', '123'],
      });
    });
  });

  describe('edge cases', () => {
    it('should handle empty string parts', () => {
      expect(parse('')).toEqual({
        scheme: 'semver',
        major: 0,
        minor: 0,
        patch: 0,
        prerelease: [],
        build: [],
      });
    });

    it('should handle v only', () => {
      expect(parse('v')).toEqual({
        scheme: 'semver',
        major: 0,
        minor: 0,
        patch: 0,
        prerelease: [],
        build: [],
      });
    });
  });

  it('should return null when given null', () => {
    expect(parse(null)).toBeNull();
  });

  it('should return undefined when given undefined', () => {
    expect(parse(undefined)).toBeUndefined();
  });

  describe('gentoo scheme', () => {
    it('defaults to semver when scheme is omitted', () => {
      expect(parse('1.2.3').scheme).toBe('semver');
    });

    it('parses a gentoo version when scheme is "gentoo"', () => {
      expect(parse('1.2.3b_rc1-r2', 'gentoo')).toEqual({
        scheme: 'gentoo',
        components: [1, 2, 3],
        letter: 'b',
        suffixes: [{ type: 'rc', number: 1 }],
        revision: 2,
      });
    });

    it('parse(v, "semver") is equivalent to parse(v)', () => {
      expect(parse('1.2.3', 'semver')).toEqual(parse('1.2.3'));
    });

    it('throws for an unrecognized scheme (bypassing the type system, as a plain-JS caller would)', () => {
      expect(() => parse('1.2.3', 'bogus' as any)).toThrow(/Unhandled version scheme/);
    });
  });

  // --- Mutation-killing tests ---

  // L42: Regex /^v/ -> /v/ (removes ^ anchor)
  // If /v/, a 'v' anywhere in the version would be removed
  it('should only strip leading v prefix', () => {
    // 'v1.0.0' should strip the leading v
    const result = parse('v1.0.0');
    expect(result?.major).toBe(1);
    // Verify the v is properly stripped by checking the output
    expect(result).toEqual({
      scheme: 'semver',
      major: 1, minor: 0, patch: 0, prerelease: [], build: []
    });
  });

  describe('debian scheme', () => {
    it('parses a debian version when scheme is "debian"', () => {
      expect(parse('1:2.30~rc1-3ubuntu2', 'debian')).toEqual({ scheme: 'debian', epoch: 1, upstream: '2.30~rc1', revision: '3ubuntu2' });
    });

    it('throws a SyntaxError on an invalid debian version', () => {
      expect(() => parse('1.0_1', 'debian')).toThrow(SyntaxError);
    });
  });
});

describe('rpm, pacman and pep440 schemes', () => {
  it('parses per scheme', () => {
    expect(parse('1:2.30~rc1-3.fc40', 'rpm')).toEqual({ scheme: 'rpm', epoch: 1, version: '2.30~rc1', release: '3.fc40' });
    expect(parse('1:2.30rc1-3', 'pacman')).toEqual({ scheme: 'pacman', epoch: 1, version: '2.30rc1', release: '3' });
    expect(parse('1.0-ALPHA.2', 'pep440')).toEqual({ scheme: 'pep440', epoch: 0, release: [1, 0], pre: { type: 'a', number: 2 }, post: null, dev: null, local: [] });
  });

  it('throws a SyntaxError on an invalid version', () => {
    expect(() => parse('1.0 2', 'rpm')).toThrow(SyntaxError);
    expect(() => parse('1.0/2', 'pacman')).toThrow(SyntaxError);
    expect(() => parse('abc', 'pep440')).toThrow(SyntaxError);
  });
});

describe('maven scheme', () => {
  it('parses into normalized items', () => {
    expect(parse('1.0a1', 'maven')).toEqual({ scheme: 'maven', items: [1n, ['alpha', [1n]]] });
  });
});

describe('prerelease identifiers with hyphens', () => {
  it('keeps everything after the first hyphen, as SemVer allows hyphens inside identifiers', () => {
    expect(parse('1.0.0-alpha-1').prerelease).toEqual(['alpha-1']);
    expect(parse('1.0.0-x-y-z.--').prerelease).toEqual(['x-y-z', '--']);
    expect(parse('1.0.0--').prerelease).toEqual(['-']);
    expect(parse('1.0.0-rc-1+build-2').prerelease).toEqual(['rc-1']);
    expect(parse('1.0.0-rc-1+build-2').build).toEqual(['build-2']);
  });

  it('round-trips through stringify', () => {
    for (const version of ['1.0.0-alpha-1', '1.0.0-x-y-z.--', '1.0.0--', '1.0.0-rc-1+build-2']) {
      expect(stringify(parse(version))).toBe(version);
    }
  });
});

