/**
 * This file is part of helpers4.
 * Copyright (C) 2025 baxyz
 * SPDX-License-Identifier: LGPL-3.0-or-later
 */

import { describe, expect, it } from 'vitest';
import { isPrerelease } from './isPrerelease';
import { parse } from './parse';

describe('isPrerelease — string input', () => {
  it('alpha prerelease → true', () => expect(isPrerelease('2.0.0-alpha.1')).toBe(true));
  it('beta prerelease → true', () => expect(isPrerelease('1.0.0-beta.0')).toBe(true));
  it('rc prerelease → true', () => expect(isPrerelease('3.0.0-rc.2')).toBe(true));
  it('arbitrary prerelease label → true', () => expect(isPrerelease('1.0.0-next')).toBe(true));
  it('stable 1.0.0 → false', () => expect(isPrerelease('1.0.0')).toBe(false));
  it('stable 2.1.3 → false', () => expect(isPrerelease('2.1.3')).toBe(false));
  it('stable 0.0.1 → false', () => expect(isPrerelease('0.0.1')).toBe(false));
  it('v-prefixed stable → false', () => expect(isPrerelease('v1.0.0')).toBe(false));
  it('v-prefixed prerelease → true', () => expect(isPrerelease('v1.0.0-alpha.3')).toBe(true));
  it('stable with build metadata containing dash → false', () => expect(isPrerelease('1.0.0+build-123')).toBe(false));
  it('stable with build metadata → false', () => expect(isPrerelease('2.0.0+build.1')).toBe(false));
});

describe('isPrerelease — ParsedVersion input', () => {
  it('parse(alpha) → true', () => expect(isPrerelease(parse('2.0.0-alpha.1'))).toBe(true));
  it('parse(beta) → true', () => expect(isPrerelease(parse('1.0.0-beta.0'))).toBe(true));
  it('parse(rc) → true', () => expect(isPrerelease(parse('3.0.0-rc.2'))).toBe(true));
  it('parse(stable) → false', () => expect(isPrerelease(parse('1.0.0'))).toBe(false));
  it('parse(stable with build) → false', () => expect(isPrerelease(parse('2.0.0+build.1'))).toBe(false));
  it('direct object with non-empty prerelease → true', () =>
    expect(isPrerelease({ scheme: 'semver', major: 1, minor: 0, patch: 0, prerelease: ['alpha', '1'], build: [] })).toBe(true));
  it('direct object with empty prerelease → false', () =>
    expect(isPrerelease({ scheme: 'semver', major: 1, minor: 0, patch: 0, prerelease: [], build: [] })).toBe(false));
});

describe('isPrerelease — null / undefined passthrough', () => {
  it('undefined → undefined', () => expect(isPrerelease(undefined)).toBeUndefined());
  it('null → null', () => expect(isPrerelease(null)).toBeNull());
});

describe('isPrerelease — gentoo scheme', () => {
  it('alpha/beta/pre/rc suffixes → true', () => {
    expect(isPrerelease('1.2.3_alpha1', 'gentoo')).toBe(true);
    expect(isPrerelease('1.2.3_beta', 'gentoo')).toBe(true);
    expect(isPrerelease('1.2.3_pre2', 'gentoo')).toBe(true);
    expect(isPrerelease('1.2.3_rc1', 'gentoo')).toBe(true);
  });

  it('p suffix → false (sorts above release, not a prerelease)', () => {
    expect(isPrerelease('1.2.3_p1', 'gentoo')).toBe(false);
  });

  it('plain release → false', () => {
    expect(isPrerelease('1.2.3', 'gentoo')).toBe(false);
  });

  it('a -r revision is not a prerelease, unlike a semver "-" suffix', () => {
    expect(isPrerelease('1.2.3-r1', 'gentoo')).toBe(false);
    // Contrast: the same string under semver treats "-r1" as a prerelease.
    expect(isPrerelease('1.2.3-r1', 'semver')).toBe(true);
  });

  it('accepts a pre-parsed ParsedGentooVersion object, scheme read from it', () => {
    expect(isPrerelease(parse('1.2.3_rc1', 'gentoo'))).toBe(true);
    expect(isPrerelease(parse('1.2.3', 'gentoo'))).toBe(false);
  });

  it('throws for an unrecognized scheme, string input (bypassing the type system)', () => {
    expect(() => isPrerelease('1.2.3', 'bogus' as any)).toThrow(/Unhandled version scheme/);
  });

  it('throws for an unrecognized scheme, object input (bypassing the type system)', () => {
    // Asserts the actual bad object is rendered as JSON, not the useless "[object Object]" a
    // bare String(version) would produce.
    expect(() => isPrerelease({ scheme: 'bogus' } as any)).toThrow('Unhandled version scheme: {"scheme":"bogus"}');
  });

  describe('debian scheme', () => {
    it('reads a ~ in the upstream part as a prerelease', () => {
      expect(isPrerelease('1.0~rc1-1', 'debian')).toBe(true);
      expect(isPrerelease('1.0-1~bpo12+1', 'debian')).toBe(false);
    });

    it('accepts a parsed debian version', () => {
      expect(isPrerelease({ scheme: 'debian', epoch: 0, upstream: '2.0~beta', revision: '' })).toBe(true);
    });
  });
});

describe('rpm, pacman and pep440 schemes', () => {
  it('detects prereleases per scheme', () => {
    expect(isPrerelease('1.0~rc1', 'rpm')).toBe(true);
    expect(isPrerelease('1.0', 'rpm')).toBe(false);
    expect(isPrerelease('1.0rc1', 'pacman')).toBe(true);
    expect(isPrerelease('1.0-1', 'pacman')).toBe(false);
    expect(isPrerelease('1.0a1', 'pep440')).toBe(true);
    expect(isPrerelease('1.0.post1', 'pep440')).toBe(false);
  });

  it('accepts a parsed version', () => {
    expect(isPrerelease({ scheme: 'pep440', epoch: 0, release: [1], pre: null, post: null, dev: 1, local: [] })).toBe(true);
  });
});

describe('maven scheme', () => {
  it('detects pre-release qualifiers', () => {
    expect(isPrerelease('1.0-SNAPSHOT', 'maven')).toBe(true);
    expect(isPrerelease('1.0-sp1', 'maven')).toBe(false);
  });
});

helpers/date/range.spec.ts.source:
/**
 * This file is part of helpers4.
 * Copyright (C) 2025 baxyz
 * SPDX-License-Identifier: LGPL-3.0-or-later
 */

import * as fc from 'fast-check';
import { describe, expect, it } from 'vitest';
import { clampDate, isWithinRange, overlaps } from './range';

const validDate = fc.date({
  min: new Date('2000-01-01'),
  max: new Date('2099-12-31'),
  noInvalidDate: true,
});

/** Returns an ordered pair [earlier, later]. */
function ordered(a: Date, b: Date): [Date, Date] {
  return a.getTime() <= b.getTime() ? [a, b] : [b, a];
}

// ---------------------------------------------------------------------------
// isWithinRange — property-based
// ---------------------------------------------------------------------------

describe('isWithinRange — property-based', () => {
  it('a date always falls within [date, date]', () => {
    fc.assert(
      fc.property(validDate, (d) => {
        expect(isWithinRange(d, d, d)).toBe(true);
      })
    );
  });

  it('start is always within [start, end]', () => {
    fc.assert(
      fc.property(validDate, validDate, (a, b) => {
        const [s, e] = ordered(a, b);
        expect(isWithinRange(s, s, e)).toBe(true);
      })
    );
  });

  it('end is always within [start, end]', () => {
    fc.assert(
      fc.property(validDate, validDate, (a, b) => {
        const [s, e] = ordered(a, b);
        expect(isWithinRange(e, s, e)).toBe(true);
      })
    );
  });
});

// ---------------------------------------------------------------------------
// clampDate — property-based
// ---------------------------------------------------------------------------

describe('clampDate — property-based', () => {
  it('clamped date is always within [min, max]', () => {
    fc.assert(
      fc.property(validDate, validDate, validDate, (d, a, b) => {
        const [lo, hi] = ordered(a, b);
        const result = clampDate(d, lo, hi)!;
        expect(result.getTime()).toBeGreaterThanOrEqual(lo.getTime());
        expect(result.getTime()).toBeLessThanOrEqual(hi.getTime());
      })
    );
  });

  it('clamping a date already in range preserves its time', () => {
    fc.assert(
      fc.property(validDate, validDate, validDate, (d, a, b) => {
        const [lo, hi] = ordered(a, b);
        if (d.getTime() >= lo.getTime() && d.getTime() <= hi.getTime()) {
          const result = clampDate(d, lo, hi)!;
          expect(result.getTime()).toBe(d.getTime());
        }
      })
    );
  });

  it('clamp is idempotent', () => {
    fc.assert(
      fc.property(validDate, validDate, validDate, (d, a, b) => {
        const [lo, hi] = ordered(a, b);
        const once = clampDate(d, lo, hi)!;
        const twice = clampDate(once, lo, hi)!;
        expect(twice.getTime()).toBe(once.getTime());
      })
    );
  });
});

// ---------------------------------------------------------------------------
// overlaps — property-based
// ---------------------------------------------------------------------------

describe('overlaps — property-based', () => {
  it('a range always overlaps with itself', () => {
    fc.assert(
      fc.property(validDate, validDate, (a, b) => {
        const [s, e] = ordered(a, b);
        expect(overlaps({ start: s, end: e }, { start: s, end: e })).toBe(true);
      })
    );
  });

  it('overlap is symmetric', () => {
    fc.assert(
      fc.property(validDate, validDate, validDate, validDate, (a, b, c, d) => {
        const [s1, e1] = ordered(a, b);
        const [s2, e2] = ordered(c, d);
        const r1 = { start: s1, end: e1 };
        const r2 = { start: s2, end: e2 };
        expect(overlaps(r1, r2)).toBe(overlaps(r2, r1));
      })
    );
  });

  it('a range contained within another always overlaps', () => {
    fc.assert(
      fc.property(validDate, validDate, validDate, validDate, (a, b, c, d) => {
        const sorted = [a, b, c, d].sort((x, y) => x.getTime() - y.getTime());
        const outer = { start: sorted[0], end: sorted[3] };
        const inner = { start: sorted[1], end: sorted[2] };
        expect(overlaps(outer, inner)).toBe(true);
      })
    );
  });
});

// ---------------------------------------------------------------------------
// Contract tests
// ---------------------------------------------------------------------------

describe('range — contract', () => {
  it('isWithinRange with string DateLike', () => {
    expect(isWithinRange('2025-06-15', '2025-01-01', '2025-12-31')).toBe(true);
  });

  it('clampDate with timestamp DateLike', () => {
    const ts = new Date('2024-06-15').getTime();
    const result = clampDate(ts, '2025-01-01', '2025-12-31');
    expect(result?.toISOString()).toContain('2025-01-01');
  });

  it('overlaps with mixed DateLike', () => {
    expect(
      overlaps(
        { start: '2025-01-01', end: new Date('2025-06-30').getTime() },
        { start: new Date('2025-03-01'), end: '2025-12-31' }
      )
    ).toBe(true);
  });

  it('invalid inputs return safe defaults', () => {
    expect(isWithinRange('nope', '2025-01-01', '2025-12-31')).toBe(false);
    expect(clampDate('nope', '2025-01-01', '2025-12-31')).toBeNull();
    expect(overlaps({ start: 'nope', end: '2025-06-30' }, { start: '2025-01-01', end: '2025-12-31' })).toBe(false);
  });
});

