      expectTypeOf(v).toEqualTypeOf<string>();
      expect(v.length).toBe(1);
    } else {
      throw new Error('expected then-branch');
    }
    const m: string | 0 | '' | null | undefined = '';
    expect(isTruthy(m)).toBe(false);
  });
});

