 * The full license information can be found in LICENSE in the root directory of this project.
 */
import { describe, expect, test, vi } from "vitest";
import { relativeURLToAbsolute } from "./relativeURLToAbsolute";

describe('relativeURLToAbsolute', () => {
    test("should use document.baseURI first", () => {
        global.document = {
            ...document,
            baseURI: "https://www.document.baseURI.com",
        };
        global.window = {
            ...window,
            location: {
                ...window.location,
                origin: "https://www.window.location.origin.com",
            },
        } as unknown as Window & typeof globalThis;

        expect(relativeURLToAbsolute("/test-url")).toBe(
            `${document.baseURI}/test-url`
        );
    });

    test("should use window.location.origin secondly", () => {
        global.document = {
            ...document,
            baseURI: undefined as unknown as string,
        };
        global.window = {
            ...window,
            location: {
                ...window.location,
                origin: "https://www.window.location.origin.com",
            },
        } as unknown as Window & typeof globalThis;

        expect(relativeURLToAbsolute("/test-url")).toBe(
            `${window.location.origin}/test-url`
        );
    });

    test("should clean URL", () => {
        global.document = {
            ...document,
            baseURI: "https://www.document.baseURI.com",
        };

        expect(relativeURLToAbsolute("test-url/////test")).toBe(
            `${document.baseURI}/test-url/test`
        );
    });

    describe('security edge cases', () => {
        test('should handle javascript: protocol in relative URL', () => {
            global.document = {
                ...document,
                baseURI: "https://www.example.com",
            };
            // javascript: in relative URL should be treated as path segment
            const result = relativeURLToAbsolute('javascript:alert(1)');
            expect(result).toContain('https://www.example.com');
            // It should be prefixed with the base URI, not execute as js
            expect(result).toBe('https://www.example.com/javascript:alert(1)');
        });

        test('should handle path traversal in relative URL', () => {
            global.document = {
                ...document,
                baseURI: "https://www.example.com",
            };
            const result = relativeURLToAbsolute('/../../../etc/passwd');
            expect(result).toContain('https://www.example.com');
        });

        test('should handle protocol-relative URL as path', () => {
            global.document = {
                ...document,
                baseURI: "https://www.example.com",
            };
            const result = relativeURLToAbsolute('//evil.com/steal');
            expect(result).toContain('https://www.example.com');
        });

        test('should handle data: URI in relative URL', () => {
            global.document = {
                ...document,
                baseURI: "https://www.example.com",
            };
            const result = relativeURLToAbsolute('data:text/html,<script>alert(1)</script>');
            expect(result).toContain('https://www.example.com');
        });

        test('should handle URL with null bytes', () => {
            global.document = {
                ...document,
                baseURI: "https://www.example.com",
            };
            const result = relativeURLToAbsolute('/path%00evil');
            expect(result).toBe('https://www.example.com/path%00evil');
        });
    });

    test("should use the given base, with no DOM at all", () => {
        vi.stubGlobal("document", undefined);
        vi.stubGlobal("window", undefined);
        expect(relativeURLToAbsolute("/api//data", "https://example.com/")).toBe("https://example.com/api/data");
        vi.unstubAllGlobals();
    });

    test("should prefer the given base over the document", () => {
        global.document = { ...document, baseURI: "https://www.document.baseURI.com" };
        expect(relativeURLToAbsolute("/x", "https://other.test")).toBe("https://other.test/x");
    });

    test("should throw a TypeError without a base nor a document", () => {
        vi.stubGlobal("document", undefined);
        vi.stubGlobal("window", undefined);
        expect(() => relativeURLToAbsolute("/x")).toThrow(TypeError);
        vi.unstubAllGlobals();
    });
});

