  });

  it('returns false for an empty map', () => {
    expect(some(new Map(), () => true)).toBe(false);
  });

  it('short-circuits after the first match', () => {
    let calls = 0;
    some(new Map([['a', 1], ['b', 2], ['c', 3]]), (v) => {
      calls++;
      return v === 1;
    });
    expect(calls).toBe(1);
