describe('template (property-based)', () => {
  it('a string with no placeholders is returned unchanged', () => {
    fc.assert(
      fc.property(
        fc.stringMatching(/^[^{}]*$/),
        fc.dictionary(fc.string(), fc.string()),
        (str, data) => {
          expect(template(str, data)).toBe(str);
        },
      ),
    );
