  it('result never contains {{...}} placeholders from the original template when all keys are provided', () => {
    fc.assert(
      fc.property(
        fc.array(
          fc.record({
            key: fc.stringMatching(/^\w+$/),
            value: fc.string(),
          }),
          { maxLength: 5 },
