  it('never mutates the input array', () => {
    fc.assert(
      fc.property(fc.array(fc.integer()), fc.integer(), (arr, item) => {
        const copy = [...arr];
        toggle(arr, item);
        expect(arr).toEqual(copy);
      }),
    );
  });
});

