    fc.assert(
      fc.property(fc.string(), (str) => {
        expect(withTrailingSlash(withTrailingSlash(str))).toBe(withTrailingSlash(str));
      }),
    );
  });
});

describe('withTrailingSlash — contract', () => {
  it('null returns null', () => {
