    expect(withTrailingSlash('foo/')).toBe('foo/');
  });

  it('no trailing slash — adds one', () => {
    expect(withTrailingSlash('foo')).toBe('foo/');
  });

  it('single slash stays single slash', () => {
    expect(withTrailingSlash('/')).toBe('/');
