  it('when nothing matches, the length grows by exactly one', () => {
    fc.assert(
      fc.property(fc.array(fc.integer({ min: 0, max: 100 })), fc.integer({ min: 1000, max: 2000 }), (arr, item) => {
        const result = replaceOrAppend(arr, item, (x) => x === item);
