    expect(isEmpty([null])).toBe(false);
    expect(isEmpty([undefined])).toBe(false);
    expect(isEmpty([0])).toBe(false);
    expect(isEmpty([''])).toBe(false);
    expect(isEmpty([false])).toBe(false);
  });

  it('should work with readonly arrays', () => {
